import { z } from 'zod';
import {
  completionCriteriaSchema,
  type CompletionCriteria,
} from '../src/intelligence/completionSchema';
import { designSelector } from '../src/intelligence/designBriefSchema';

// Share selectors and citations; IDs and prose labels are presentation data
// generated by the host. The model only interprets intent into predicates.
function objects(schema: z.ZodType): z.ZodObject<any>[] {
  if (schema instanceof z.ZodUnion)
    return schema.options.flatMap((s) => objects(s as z.ZodType));
  return [schema as z.ZodObject<any>];
}
const requirements = objects(
  completionCriteriaSchema.shape.checks.element.shape.requirement,
).map((s) => {
  let compact = s.omit({ id: true, label: true });
  for (const key of ['selector', 'first', 'second'])
    if (key in s.shape)
      compact = compact.extend({ [key]: z.number().int().min(0).max(63) });
  return compact.strict();
});
export const completionWireSchema = z
  .object({
    modeling: z.boolean(),
    editable: completionCriteriaSchema.shape.editable,
    selections: z.array(designSelector).max(64),
    evidence: z
      .array(
        z
          .object({
            source: z.enum(['request', 'history', 'reference']),
            text: z.string().min(1).max(400),
          })
          .strict(),
      )
      .max(32),
    checks: z
      .array(
        z
          .object({
            because: z.number().int().min(0).max(31),
            calculation:
              completionCriteriaSchema.shape.checks.element.shape.calculation
                .unwrap()
                .nullable(),
            test: z.union([requirements[0], ...requirements.slice(1)]),
          })
          .strict(),
      )
      .max(32),
    qualitativeLimits: completionCriteriaSchema.shape.qualitativeLimits,
  })
  .strict();

// Correction is a small patch to named invalid checks, not another full brief.
// Selectors refer to the original compact selections; citations and edit scope
// are copied by the host and cannot be rewritten by the correction reader.
export const completionCorrectionWireSchema = z
  .object({
    corrections: z
      .array(
        z
          .object({
            checkId: z.string().min(1).max(60),
            test: z.union([requirements[0], ...requirements.slice(1)]),
          })
          .strict(),
      )
      .max(32),
  })
  .strict();

export function expandCompletionCorrections(
  raw: unknown,
  previous: CompletionCriteria,
): CompletionCriteria {
  const wire = completionCorrectionWireSchema.parse(raw);
  const compact = compactCompletionCriteria(previous);
  const patches = new Map(wire.corrections.map((c) => [c.checkId, c.test]));
  if (
    patches.size !== wire.corrections.length ||
    [...patches.keys()].some(
      (id) => !previous.checks.some((c) => c.requirement.id === id),
    )
  )
    throw new Error('Correction must identify distinct existing checks.');
  return completionCriteriaSchema.parse({
    ...previous,
    checks: previous.checks.map((c) => {
      const patch = patches.get(c.requirement.id);
      if (!patch) return c;
      const test = { ...patch } as Record<string, unknown>;
      for (const key of ['selector', 'first', 'second'])
        if (key in test) {
          const selection = compact.selections[test[key] as number];
          if (!selection)
            throw new Error('Correction references an unknown selection.');
          test[key] = selection;
        }
      return {
        ...c,
        requirement: {
          ...test,
          id: c.requirement.id,
          label: c.requirement.label,
        },
      };
    }),
  });
}

export function expandCompletionWire(raw: unknown): CompletionCriteria {
  const wire = completionWireSchema.parse(raw);
  return completionCriteriaSchema.parse({
    modeling: wire.modeling,
    editable: wire.editable,
    qualitativeLimits: wire.qualitativeLimits,
    checks: wire.checks.map((c, i) => {
      const citation = wire.evidence[c.because];
      if (!citation) throw new Error('Unknown completion evidence reference.');
      const test = { ...(c.test as Record<string, unknown>) };
      for (const key of ['selector', 'first', 'second'])
        if (key in test) {
          const selection = wire.selections[test[key] as number];
          if (!selection)
            throw new Error('Unknown completion selection reference.');
          test[key] = selection;
        }
      const selection = test.selector as
        z.infer<typeof designSelector> | undefined;
      const title = String(test.metric ?? test.kind).replaceAll('_', ' ');
      return {
        source: citation.source,
        evidence: citation.text,
        ...(c.calculation ? { calculation: c.calculation } : {}),
        requirement: {
          ...test,
          id: `check-${i + 1}`,
          label: `${title}${selection?.nameContains ? ` · ${selection.nameContains}` : ''}`,
        },
      };
    }),
  });
}

// Used to quantify wire size and replay saved criteria in offline SDK tests.
export function compactCompletionCriteria(criteria: CompletionCriteria) {
  const selections: z.infer<typeof designSelector>[] = [],
    evidence: { source: string; text: string }[] = [];
  const index = (array: any[], value: unknown) => {
    let i = array.findIndex((v) => JSON.stringify(v) === JSON.stringify(value));
    if (i < 0) {
      i = array.length;
      array.push(value);
    }
    return i;
  };
  return completionWireSchema.parse({
    modeling: criteria.modeling,
    editable: criteria.editable,
    qualitativeLimits: criteria.qualitativeLimits,
    selections,
    evidence,
    checks: criteria.checks.map((c) => {
      const { id: _id, label: _label, ...test } = c.requirement as any;
      for (const key of ['selector', 'first', 'second'])
        if (key in test) test[key] = index(selections, test[key]);
      return {
        because: index(evidence, { source: c.source, text: c.evidence }),
        calculation: c.calculation ?? null,
        test,
      };
    }),
  });
}
